'use strict'
const assert = require('node:assert/strict')
const fs = require('node:fs')
const path = require('node:path')
// js-yaml is already frozen by frontend/package-lock.json (ESLint's dependency).
const yaml = require(require.resolve('js-yaml', { paths: [process.cwd()] }))
const validate = require('./check-workflow.cjs')
const root = __dirname
const document = yaml.load(fs.readFileSync(path.join(root, 'workflow.yml'), 'utf8'))
const config = fs.readFileSync(path.join(root, 'project.toml'), 'utf8')
const baseline = () => structuredClone(document)
assert.doesNotThrow(() => validate(baseline(), config))
const negative = (name, change) => {
  const value = baseline()
  change(value)
  assert.throws(() => validate(value, config), undefined, name)
}
negative('missing required dependency', value => { value.jobs['ci-required'].needs = ['frontend'] })
negative('gate is conditional on success', value => { value.jobs['ci-required'].if = 'success()' })
negative('fabricated backend success', value => { value.jobs['ci-required'].steps[1].env.BACKEND_RESULT = 'success' })
negative('wrong frontend result', value => { value.jobs['ci-required'].steps[1].env.FRONTEND_RESULT = '${{ needs.backend.result }}' })
negative('gate command ignores results', value => { value.jobs['ci-required'].steps[1].run = 'echo success' })
negative('ignored check failure', value => { value.jobs.backend.steps[3]['continue-on-error'] = true })
negative('ignored cleanup failure', value => { value.jobs.backend.steps.at(-1).run += ' || true' })
negative('missing backend test command', value => { value.jobs.backend.steps = value.jobs.backend.steps.filter(step => step.name !== 'Backend tests') })
negative('missing frontend build', value => { value.jobs.frontend.steps = value.jobs.frontend.steps.filter(step => step.name !== 'Production build') })
negative('mutable action tag', value => { value.jobs.backend.steps[0].uses = 'actions/checkout@v7' })
negative('checkout credential persistence', value => { value.jobs.backend.steps[0].with['persist-credentials'] = true })
negative('write permission', value => { value.permissions.contents = 'write' })
negative('untrusted privileged trigger', value => { value.on.pull_request_target = {} })
negative('missing mandatory PR run', value => { value.on.pull_request.paths = ['frontend/**'] })
negative('main runs cancel each other', value => { value.concurrency['cancel-in-progress'] = true })
negative('main group reused', value => { value.concurrency.group = '${{ github.ref }}' })
negative('test-only manual checks', value => { value.on.workflow_dispatch = {} })
negative('missing PostgreSQL readiness', value => { value.jobs.backend.steps = value.jobs.backend.steps.filter(step => step.name !== 'PostgreSQL') })
negative('migration before PostgreSQL readiness', value => { const steps = value.jobs.backend.steps; const p = steps.findIndex(step => step.name === 'PostgreSQL'); [steps[p], steps[p + 1]] = [steps[p + 1], steps[p]] })
negative('aggregate step conditional on backend success', value => { value.jobs['ci-required'].steps[1].if = '${{ needs.backend.result == "success" }}' })
negative('aggregate step never executes', value => { value.jobs['ci-required'].steps[1].if = false })
negative('aggregate shell override', value => { value.jobs['ci-required'].steps[1].shell = 'bash --noprofile --norc {0}; true' })
negative('aggregate working directory override', value => { value.jobs['ci-required'].steps[1]['working-directory'] = '/tmp' })
negative('workflow shell default override', value => { value.defaults = { run: { shell: 'bash {0}; true' } } })
negative('workflow environment override', value => { value.env = { BASH_ENV: '/tmp/ignore-errors' } })
negative('backend execution defaults', value => { value.jobs.backend.defaults = { run: { shell: 'bash {0}' } } })
negative('aggregate job environment override', value => { value.jobs['ci-required'].env = { BACKEND_RESULT: 'success' } })
negative('missing required status tests', value => { value.jobs.frontend.steps = value.jobs.frontend.steps.filter(step => step.name !== 'Required status truth table') })
negative('additional masked command', value => { value.jobs.backend.steps.splice(2, 0, { name: 'Mask', run: 'false; true' }) })
negative('bracket secret reference', value => { value.jobs.backend.steps[3].env = { TOKEN: "${{ secrets['TOKEN'] }}" } })
negative('implicit GitHub token reference', value => { value.jobs.backend.steps[3].env = { TOKEN: '${{ github.token }}' } })
negative('missing workflow inspection', value => { value.jobs.frontend.steps = value.jobs.frontend.steps.filter(step => step.name !== 'Workflow wiring and negative fixtures') })
console.log('workflow: valid configuration and 32 negative fixtures passed')
